#!/usr/bin/env python3
"""Writes kit-api-<version>.json: every public name each kit module defines at a released tag, Python by its AST
(top-level def, class and assignment without a leading underscore) and Node by its module's exports. The kit's
facades must keep every one (FAA-65); test_kit_api.py and kit-api.test.mjs hold them to it.

    python3 test/fixtures/kit-api/make_snapshot.py <tree extracted from `git archive <tag> plugins`> <version>
"""
import ast
import json
import subprocess
import sys
from pathlib import Path

DIRS = ["building-fabric-services/scripts", "working-with-fabric/scripts"]


def python_names(path: Path) -> list:
    names = set()
    for node in ast.parse(path.read_text(encoding="utf-8")).body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, ast.Assign):
            names.update(t.id for t in node.targets if isinstance(t, ast.Name))
        elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
            names.add(node.target.id)
    return sorted(n for n in names if not n.startswith("_"))


def node_names(path: Path) -> list:
    script = "import(process.argv[1]).then((m) => console.log(JSON.stringify(Object.keys(m).sort())))"
    out = subprocess.run(["node", "-e", script, path.resolve().as_uri()], capture_output=True, text=True, check=True)
    return json.loads(out.stdout)


def main(root: str, version: str) -> None:
    skills = Path(root) / "plugins/fabric-agent-adapter/skills"
    api = {"python": {}, "node": {}}
    for d in DIRS:
        for path in sorted((skills / d).glob("*.py")):
            api["python"][path.stem] = python_names(path)
        for path in sorted((skills / d).glob("*.mjs")):
            if not path.name.startswith(("sample-", "check_")):  # programs that run when imported, not libraries
                api["node"][path.stem] = node_names(path)
    out = Path(__file__).with_name("kit-api-%s.json" % version)
    out.write_text(json.dumps({"version": version, "about": "Public names each kit module defined at v%s; generated by make_snapshot.py, never edited by hand." % version, **api}, indent=1) + "\n", encoding="utf-8")
    print("%s: %d Python modules, %d Node modules" % (out.name, len(api["python"]), len(api["node"])))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
